1584.     pub open spec fn init(self) -> StatePred<ClusterState> {
1585.         |s: ClusterState| {
1586.             // The API server is initialized...
1587.             &&& (api_server(self.installed_types).init)(s.api_server)
1588.             // and the built-in controllers are initialized...
1589.             &&& (builtin_controllers().init)(())
1590.             // and the network is initialized...
1591.             &&& (network().init)(s.network)
1592.             // and message drop is enabled...
1593.             &&& s.req_drop_enabled
1594.             // and pod monkey is enabled...
1595.             &&& s.pod_monkey_enabled
1596.             // and for each controller...
1597.             &&& forall |key| #[trigger] self.controller_models.contains_key(key)
1598.                 ==> {
1599.                     let model = self.controller_models[key];
1600.                     // its internal state exists...
1601.                     &&& s.controller_and_externals.contains_key(key)
1602.                     // and is initialized...
1603.                     &&& (controller(model.reconcile_model, key).init)(s.controller_and_externals[key].controller)
1604.                     // and crash for this controller is enabled...
1605.                     &&& s.controller_and_externals[key].crash_enabled
1606.                     // and if the controller has an associated external system...
1607.                     &&& model.external_model is Some
1608.                         ==> {
1609.                             // the internal state of that external system exists...
1610.                             &&& s.controller_and_externals[key].external is Some
1611.                             // and is initialized.
1612.                             &&& (external(model.external_model->0).init)(s.controller_and_externals[key].external->0)
1613.                         }
1614.                 }
1615.         }
1616.     }
