2734. pub struct StateMachine <State, Input, ActionInput, Output, Step> {
2735.     // Check if it is the initial internal state.
2736.     pub init: spec_fn(State) -> bool,
2737. 
2738.     // The set of actions the state machine can take.
2739.     pub actions: Set<Action<State, ActionInput, Output>>,
2740. 
2741.     // Return the corresponding action of the binding step.
2742.     pub step_to_action: spec_fn(Step) -> Action<State, ActionInput, Output>,
2743. 
