2748. impl<State, Input, ActionInput, Output, Step> StateMachine<State, Input, ActionInput, Output, Step> {
2749. 
2750.     pub open spec fn next_result(self, input: Input, s: State) -> ActionResult<State, Output> {
2751.         if exists |step| (#[trigger] (self.step_to_action)(step).precondition)((self.action_input)(step, input), s) {
2752.             let witness_step = choose |step| (#[trigger] (self.step_to_action)(step).precondition)((self.action_input)(step, input), s);
2753.             let action = (self.step_to_action)(witness_step);
2754.             let action_input = (self.action_input)(witness_step, input);
2755.             ActionResult::Enabled((action.transition)(action_input, s).0, (action.transition)(action_input, s).1)
2756.         } else {
2757.             ActionResult::Disabled
2758.         }
2759.     }
2760. 
2761. }
