3067. #[verifier(inline)]
3068. pub open spec fn handle_create_request(installed_types: InstalledTypes, req: CreateRequest, s: APIServerState) -> (APIServerState, CreateResponse) {
3069.     if create_request_admission_check(installed_types, req, s) is Some {
3070.         // Creation fails.
3071.         (s, CreateResponse{res: Err(create_request_admission_check(installed_types, req, s)->0)})
3072.     } else {
3073.         let created_obj = DynamicObjectView {
3074.             kind: req.obj.kind,
3075.             metadata: ObjectMetaView {
3076.                 // Set name for new object if name is not provided, here we generate
3077.                 // a unique name. The uniqueness is guaranteed by generated_name_is_unique.
3078.                 name: if req.obj.metadata.name is Some {
3079.                     req.obj.metadata.name
3080.                 } else {
3081.                     Some(generate_name(s))
3082.                 },
3083.                 namespace: Some(req.namespace), // Set namespace for new object
3084.                 resource_version: Some(s.resource_version_counter), // Set rv for new object
3085.                 uid: Some(s.uid_counter), // Set uid for new object
3086.                 deletion_timestamp: None, // Unset deletion timestamp for new object
3087.                 ..req.obj.metadata
3088.             },
3089.             spec: req.obj.spec,
3090.             status: marshalled_default_status(req.obj.kind, installed_types), // Overwrite the status with the default one
3091.         };
3092.         if s.resources.contains_key(created_obj.object_ref()) {
3093.             // Note 1: You might find this branch redundant since we already have
3094.             // generated_name_is_unique which guarantees that the created_obj's
3095.             // key is different from any existing keys even if name was not provided.
3096.             // But we still add this branch just to avoid calling generated_name_is_unique
3097.             // when we want to show that create without a provided name does not override
3098.             // an existing object when writing proofs.
3099.             //
3100.             // Note 2: Adding this branch also means that if we want to prove the object
3101.             // is eventually created by a create request without the name provided,
3102.             // we need to explicitly call generated_name_is_unique to show that
3103.             // we do not fall into this branch.
3104.             (s, CreateResponse{res: Err(APIError::ObjectAlreadyExists)})
3105.         } else if created_object_validity_check(created_obj, installed_types) is Some {
3106.             // Creation fails.
3107.             (s, CreateResponse{res: Err(created_object_validity_check(created_obj, installed_types)->0)})
3108.         } else {
3109.             // Creation succeeds.
3110.             (APIServerState {
3111.                 resources: s.resources.insert(created_obj.object_ref(), created_obj),
3112.                 uid_counter: s.uid_counter + 1,
3113.                 resource_version_counter: s.resource_version_counter + 1,
3114.                 ..s
3115.             }, CreateResponse{res: Ok(created_obj)})
3116.         }
3117.     }
3118. }
