3140. pub uninterp spec fn deletion_timestamp() -> StringView;
3141. 
3142. pub open spec fn handle_delete_request(req: DeleteRequest, s: APIServerState) -> (APIServerState, DeleteResponse) {
3143.     if delete_request_admission_check(req, s) is Some {
3144.         // Deletion fails.
3145.         (s, DeleteResponse{res: Err(delete_request_admission_check(req, s)->0)})
3146.     } else {
3147.         // Deletion succeeds.
3148.         let obj = s.resources[req.key];
3149.         if obj.metadata.finalizers is Some && obj.metadata.finalizers->0.len() > 0 {
3150.             // With the finalizer(s) in the object, we cannot immediately delete it from the key-value store.
3151.             // Instead, we set the deletion timestamp of this object.
3152.             // If the object already has a deletion timestamp, then skip.
3153.             //
3154.             // NOTE: Having finalizer(s) is not the only reason that a deletion is postponed. Having a graceful
3155.             // period set in the deletion option is another reason. Currently we do not model the graceful period
3156.             // option so we don't model how the API server checks whether a deletion should be graceful.
3157.             // However, even without a graceful period option, deleting a Pod can still be graceful depending on its
3158.             // spec content (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/apis/core/types.go#L3256)
3159.             // because Pod implements CheckGracefulDelete (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/registry/core/pod/strategy.go#L168).
3160.             // This is irrelevant to application controllers that do not manage pods, and acceptable for verifying
3161.             // low-level built-in controllers because they are supposed to treat terminating pods as non-existing pods.
3162.             if obj.metadata.deletion_timestamp is Some {
3163.                 // A deletion timestamp is already set so no need to bother it.
3164.                 (s, DeleteResponse{res: Ok(())})
3165.             } else {
3166.                 let stamped_obj_with_new_rv = obj.with_deletion_timestamp(deletion_timestamp())
3167.                                                  .with_resource_version(s.resource_version_counter);
3168.                 (APIServerState {
3169.                     // Here we use req.key, instead of stamped_obj.object_ref(), to insert to the map.
3170.                     // This is intended because using stamped_obj.object_ref() will require us to use
3171.                     // the invariant each_object_in_etcd_is_well_formed a lot more frequently:
3172.                     // we need this invariant to convince Verus that the stamped_obj is well formed
3173.                     // so the key we use to insert to the map is the same as req.key.
3174.                     resources: s.resources.insert(req.key, stamped_obj_with_new_rv),
3175.                     resource_version_counter: s.resource_version_counter + 1,
3176.                     ..s
3177.                 }, DeleteResponse{res: Ok(())})
3178.             }
3179.         } else {
3180.             // The object can be immediately removed from the key-value store.
3181.             //
3182.             // NOTE: In some very corner case, the API server *seems* to first updates the object (to update its finalizers)
3183.             // and then deletes the object immediately, which makes the entire Delete operation not atomic.
3184.             // However, this only happens in the orphan or foreground deletion mode, so we do not model this
3185.             // seemingly non-atomic behavior for now.
3186.             // For more details, see how the API server updates the object in the middle of handling deletion requests:
3187.             // https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L1009
3188.             (APIServerState {
3189.                 resources: s.resources.remove(req.key),
3190.                 resource_version_counter: s.resource_version_counter + 1,
3191.                 ..s
3192.             }, DeleteResponse{res: Ok(())})
3193.         }
3194.     }
3195. }
