3247. pub open spec fn update_request_admission_check(installed_types: InstalledTypes, req: UpdateRequest, s: APIServerState) -> Option<APIError> {
3248.     update_request_admission_check_helper(installed_types, req.name, req.namespace, req.obj, s)
3249. }
