3251. pub open spec fn updated_object(req: UpdateRequest, old_obj: DynamicObjectView) -> DynamicObjectView {
3252.     let updated_obj = DynamicObjectView {
3253.         kind: req.obj.kind,
3254.         metadata: ObjectMetaView {
3255.             namespace: Some(req.namespace), // Overwrite namespace since it might not be provided
3256.             resource_version: old_obj.metadata.resource_version, // Overwrite rv since it might not be provided
3257.             uid: old_obj.metadata.uid, // Overwrite uid since it might not be provided
3258.             deletion_timestamp: old_obj.metadata.deletion_timestamp, // Ignore any change to deletion_timestamp
3259.             ..req.obj.metadata
3260.         },
3261.         spec: req.obj.spec,
3262.         status: old_obj.status, // Ignore any change to status
3263.     };
3264.     updated_obj
3265. }
