3267. pub open spec fn updated_object_validity_check(updated_obj: DynamicObjectView, old_obj: DynamicObjectView, installed_types: InstalledTypes) -> Option<APIError> {
3268.     if metadata_validity_check(updated_obj) is Some {
3269.         metadata_validity_check(updated_obj)
3270.     } else if metadata_transition_validity_check(updated_obj, old_obj) is Some {
3271.         metadata_transition_validity_check(updated_obj, old_obj)
3272.     } else if object_validity_check(updated_obj, installed_types) is Some {
3273.         object_validity_check(updated_obj, installed_types)
3274.     } else if object_transition_validity_check(updated_obj, old_obj, installed_types) is Some {
3275.         object_transition_validity_check(updated_obj, old_obj, installed_types)
3276.     } else {
3277.         None
3278.     }
3279. }
