3281. #[verifier(inline)]
3282. pub open spec fn handle_update_request(installed_types: InstalledTypes, req: UpdateRequest, s: APIServerState) -> (APIServerState, UpdateResponse) {
3283.     if update_request_admission_check(installed_types, req, s) is Some {
3284.         // Update fails.
3285.         (s, UpdateResponse{res: Err(update_request_admission_check(installed_types, req, s)->0)})
3286.     } else {
3287.         let old_obj = s.resources[req.key()];
3288.         let updated_obj = updated_object(req, old_obj);
3289.         if updated_obj == old_obj {
3290.             // Update is a noop because there is nothing to update
3291.             // so the resource version counter does not increase here,
3292.             // and the resource version of this object remains the same.
3293.             (s, UpdateResponse{res: Ok(old_obj)})
3294.         } else {
3295.             // Update changes something in the object (either in spec or metadata), so we set it a newer resource version,
3296.             // which is the current rv counter.
3297.             let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3298.             if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3299.                 // Update fails.
3300.                 (s, UpdateResponse{res: Err(updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types)->0)})
3301.             } else {
3302.                 // Update succeeds.
3303.                 if updated_obj_with_new_rv.metadata.deletion_timestamp is None
3304.                     || (updated_obj_with_new_rv.metadata.finalizers is Some
3305.                         && updated_obj_with_new_rv.metadata.finalizers->0.len() > 0)
3306.                 {
3307.                     // The regular update case, where the object has no deletion timestamp set
3308.                     // or has at least one finalizer.
3309.                     (APIServerState {
3310.                         resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3311.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3312.                         ..s
3313.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3314.                 } else {
3315.                     // The delete-during-update case, where the update removes the finalizers from
3316.                     // the object that has a deletion timestamp, so the object needs to be deleted now.
3317.                     //
3318.                     // NOTE: in the actual implementation, when handling an update request,
3319.                     // the API server first applies the update to the object in the key-value store,
3320.                     // then checks whether the object can be deleted.
3321.                     // If so, it continues to delete the object from the key-value store before replying
3322.                     // to the update request.
3323.                     // This means that there is a super short window where the object has been updated in the store
3324.                     // (with a deletion timestamp and without any finalizer), but has not been deleted yet.
3325.                     // This behavior, strictly speaking, makes the entire Update operation not atomic.
3326.                     // We choose to still model the Update operation as an atomic step for simplicity.
3327.                     // This design choice does not affect the correctness of the controller that issues Update
3328.                     // in a blocking manner because the controller will never observe this intermediate state between
3329.                     // the update and deletion.
3330.                     // More generally speaking, this modeling won't affect the correctness of any controller that
3331.                     // treats a terminating object without finalizers as a non-existing object --- a good practice
3332.                     // controllers should follow.
3333.                     //
3334.                     // NOTE: the API server should also check whether the deletion grace period in the metadata
3335.                     // is set to 0 before deleting the object in case of graceful deletion
3336.                     // (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L533).
3337.                     // Here we omit that condition because graceful deletion is not supported.
3338.                     (APIServerState {
3339.                         resources: s.resources.remove(updated_obj_with_new_rv.object_ref()),
3340.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3341.                         ..s
3342.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3343.                 }
3344.             }
3345.         }
3346.     }
3347. }
