3636. pub open spec fn run_scheduled_reconcile(model: ReconcileModel) -> ControllerAction {
3637.     Action {
3638.         precondition: |input: ControllerActionInput, s: ControllerState| {
3639.             &&& input.scheduled_cr_key is Some
3640.             &&& input.scheduled_cr_key->0.kind == model.kind
3641.             &&& s.scheduled_reconciles.contains_key(input.scheduled_cr_key->0)
3642.             &&& input.recv is None
3643.             &&& !s.ongoing_reconciles.contains_key(input.scheduled_cr_key->0)
3644.         },
3645.         transition: |input: ControllerActionInput, s: ControllerState| {
3646.             let cr_key = input.scheduled_cr_key->0;
3647.             let (new_allocator, reconcile_id) = s.reconcile_id_allocator.allocate();
3648.             let initialized_ongoing_reconcile = OngoingReconcile {
3649.                 triggering_cr: s.scheduled_reconciles[cr_key],
3650.                 pending_req_msg: None,
3651.                 local_state: (model.init)(),
3652.                 reconcile_id: reconcile_id
3653.             };
3654.             let s_prime = ControllerState {
3655.                 ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, initialized_ongoing_reconcile),
3656.                 scheduled_reconciles: s.scheduled_reconciles.remove(cr_key),
3657.                 reconcile_id_allocator: new_allocator,
3658.                 ..s
3659.             };
3660.             let output = ControllerActionOutput {
3661.                 send: Multiset::empty(),
3662.                 rpc_id_allocator: input.rpc_id_allocator,
3663.             };
3664.             (s_prime, output)
3665.         },
3666.     }
3667. }
