3669. pub open spec fn continue_reconcile(model: ReconcileModel, controller_id: int) -> ControllerAction {
3670.     Action {
3671.         precondition: |input: ControllerActionInput, s: ControllerState| {
3672.             if input.scheduled_cr_key is Some {
3673.                 let cr_key = input.scheduled_cr_key->0;
3674. 
3675.                 &&& cr_key.kind == model.kind
3676.                 &&& s.ongoing_reconciles.contains_key(cr_key)
3677.                 &&& !(model.done)(s.ongoing_reconciles[cr_key].local_state)
3678.                 &&& !(model.error)(s.ongoing_reconciles[cr_key].local_state)
3679.                 &&& if s.ongoing_reconciles[cr_key].pending_req_msg is Some {
3680.                     &&& input.recv is Some
3681.                     &&& (input.recv->0.content.is_APIResponse() || input.recv->0.content.is_ExternalResponse())
3682.                     &&& resp_msg_matches_req_msg(input.recv->0, s.ongoing_reconciles[cr_key].pending_req_msg->0)
3683.                 } else {
3684.                     input.recv is None
3685.                 }
3686.             } else {
3687.                 false
3688.             }
3689.         },
3690.         transition: |input: ControllerActionInput, s: ControllerState| {
3691.             let cr_key = input.scheduled_cr_key->0;
3692.             let reconcile_state = s.ongoing_reconciles[cr_key];
3693.             let resp_o = if input.recv is Some {
3694.                 if input.recv->0.content.is_APIResponse() {
3695.                     Some(ResponseContent::KubernetesResponse(input.recv->0.content.get_APIResponse_0()))
3696.                 } else {
3697.                     Some(ResponseContent::ExternalResponse(input.recv->0.content.get_ExternalResponse_0()))
3698.                 }
3699.             } else {
3700.                 None
3701.             };
3702.             let (local_state_prime, req_o) = (model.transition)(reconcile_state.triggering_cr, resp_o, reconcile_state.local_state);
3703.             let (pending_req_msg, send, rpc_id_allocator_prime) = if req_o is Some {
3704.                 let pending_req_msg = match req_o->0 {
3705.                     RequestContent::KubernetesRequest(req) => {
3706.                         Some(controller_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
3707.                     },
3708.                     RequestContent::ExternalRequest(req) => {
3709.                         Some(controller_external_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
3710.                     }
3711.                 };
3712.                 (pending_req_msg, Multiset::singleton(pending_req_msg->0), input.rpc_id_allocator.allocate().0)
3713.             } else {
3714.                 (None, Multiset::empty(), input.rpc_id_allocator)
3715.             };
3716. 
3717.             let reconcile_state_prime = OngoingReconcile {
3718.                 pending_req_msg: pending_req_msg,
3719.                 local_state: local_state_prime,
3720.                 ..reconcile_state
3721.             };
3722.             let s_prime = ControllerState {
3723.                 ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, reconcile_state_prime),
3724.                 ..s
3725.             };
3726.             let output = ControllerActionOutput {
3727.                 send: send,
3728.                 rpc_id_allocator: rpc_id_allocator_prime,
3729.             };
3730.             (s_prime, output)
3731.         }
3732.     }
3733. }
