1639.     pub open spec fn api_server_next(self) -> Action<ClusterState, Option<Message>, ()> {
1640.         let result = |input: Option<Message>, s: ClusterState| {
1641.             let host_result = self.api_server().next_result(
1642.                 APIServerActionInput{ recv: input },
1643.                 s.api_server
1644.             );
1645.             let msg_ops = MessageOps {
1646.                 recv: input,
1647.                 send: host_result.get_Enabled_1().send,
1648.             };
1649.             let network_result = network().next_result(msg_ops, s.network);
1650. 
1651.             (host_result, network_result)
1652.         };
1653.         Action {
1654.             precondition: |input: Option<Message>, s: ClusterState| {
1655.                 &&& received_msg_destined_for(input, HostId::APIServer)
1656.                 &&& result(input, s).0.is_Enabled()
1657.                 &&& result(input, s).1.is_Enabled()
1658.             },
1659.             transition: |input: Option<Message>, s: ClusterState| {
1660.                 let (host_result, network_result) = result(input, s);
1661.                 (ClusterState {
1662.                     api_server: host_result.get_Enabled_0(),
1663.                     network: network_result.get_Enabled_0(),
1664.                     ..s
1665.                 }, ())
1666.             },
1667.         }
1668.     }
