2446.                     let filtered_pods = filter_pods(pods, v_replica_set);
2447.                     let replicas = v_replica_set.spec.replicas.unwrap_or(0);
2448.                     if replicas < 0 {
2449.                         (error_state(state), None)
2450.                     } else {
2451.                         let desired_replicas = replicas;
2452.                         if filtered_pods.len() == desired_replicas {
2453.                             let state_prime = VReplicaSetReconcileState {
