2466.                                 reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2467.                                 ..state
2468.                             };
2469.                             (state_prime, Some(RequestView::KRequest(req)))
2470.                         } else {
2471.                             let diff = filtered_pods.len() - desired_replicas;
2472.                             let pod_name_or_none = filtered_pods[diff - 1].metadata.name;
2473.                             if pod_name_or_none.is_none() {
2474.                                 (error_state(state), None)
