3037. pub open spec fn create_request_admission_check(installed_types: InstalledTypes, req: CreateRequest, s: APIServerState) -> Option<APIError> {
3038.     if req.obj.metadata.name is None && req.obj.metadata.generate_name is None {
3039.         // Creation fails because neither the name nor the generate_name of the provided object is provided
3040.         Some(APIError::Invalid)
3041.     } else if req.obj.metadata.namespace is Some && req.namespace != req.obj.metadata.namespace->0 {
3042.         // Creation fails because the namespace of the provided object does not match the namespace sent on the request
3043.         Some(APIError::BadRequest)
3044.     } else if !unmarshallable_object(req.obj, installed_types) {
3045.         // Creation fails because the provided object is not well formed
3046.         Some(APIError::BadRequest) // TODO: should the error be BadRequest?
3047.     } else if req.obj.metadata.name is Some && s.resources.contains_key(req.obj.with_namespace(req.namespace).object_ref()) {
3048.         // Creation fails because the object has a name and it already exists
3049.         Some(APIError::ObjectAlreadyExists)
3050.     } else {
3051.         None
3052.     }
3053. }
