3120. pub open spec fn delete_request_admission_check(req: DeleteRequest, s: APIServerState) -> Option<APIError> {
3121.     if !s.resources.contains_key(req.key) {
3122.         // Deletion fails because the object does not exist
3123.         Some(APIError::ObjectNotFound)
3124.     } else if req.preconditions is Some {
3125.         let preconditions = req.preconditions->0;
3126.         if preconditions.uid is Some && preconditions.uid != s.resources[req.key].metadata.uid {
3127.             // Deletion fails because the uid of the object does not match the uid in the precondition
3128.             Some(APIError::Conflict)
3129.         } else if preconditions.resource_version is Some && preconditions.resource_version != s.resources[req.key].metadata.resource_version {
3130.             // Deletion fails because the resource version of the object does not match the resource version in the precondition
3131.             Some(APIError::Conflict)
3132.         } else {
3133.             None
3134.         }
3135.     } else {
3136.         None
3137.     }
3138. }
