3204. pub open spec fn update_request_admission_check_helper(installed_types: InstalledTypes, name: StringView, namespace: StringView, obj: DynamicObjectView, s: APIServerState) -> Option<APIError> {
3205.     let key = ObjectRef {
3206.         kind: obj.kind,
3207.         namespace: namespace,
3208.         name: name,
3209.     };
3210.     if obj.metadata.name is None {
3211.         // Update fails because the name of the object is not provided
3212.         Some(APIError::BadRequest)
3213.     } else if name != obj.metadata.name->0 {
3214.         // Update fails because the name of the provided object
3215.         // does not match the name sent on the request
3216.         Some(APIError::BadRequest)
3217.     } else if obj.metadata.namespace is Some
3218.         && namespace != obj.metadata.namespace->0 {
3219.         // Update fails because the namespace of the provided object
3220.         // does not match the namespace sent on the request
3221.         Some(APIError::BadRequest)
3222.     } else if !unmarshallable_object(obj, installed_types) {
3223.         // Update fails because the provided object is not well formed
3224.         // TODO: should the error be BadRequest?
3225.         Some(APIError::BadRequest)
3226.     } else if !s.resources.contains_key(key) {
3227.         // Update fails because the object does not exist
3228.         // TODO: check AllowCreateOnUpdate() to see whether to support create-on-update
3229.         Some(APIError::ObjectNotFound)
3230.     } else if obj.metadata.resource_version is None
3231.         && !allow_unconditional_update(key.kind) {
3232.         // Update fails because the object does not provide a rv and unconditional update is not supported
3233.         Some(APIError::Invalid)
3234.     } else if obj.metadata.resource_version is Some
3235.         && obj.metadata.resource_version != s.resources[key].metadata.resource_version {
3236.         // Update fails because the object has a wrong rv
3237.         Some(APIError::Conflict)
3238.     } else if obj.metadata.uid is Some
3239.         && obj.metadata.uid != s.resources[key].metadata.uid {
3240.         // Update fails because the object has a wrong uid
3241.         Some(APIError::Conflict)
3242.     } else {
3243.         None
3244.     }
3245. }
