3447. pub open spec fn handle_get_then_delete_request_msg(msg: Message, s: APIServerState) -> (APIServerState, Message)
3448.     recommends
3449.         msg.content.is_get_then_delete_request(),
3450. {
3451.     let req = msg.content.get_get_then_delete_request();
3452.     // Step 1: get the object
3453.     let get_req = GetRequest {
3454.         key: req.key
3455.     };
3456.     let get_resp = handle_get_request(get_req, s);
3457.     match get_resp.res {
3458.         Ok(_) => {
3459.             let current_obj = s.resources[req.key()];
3460.             // Step 2: if the object exists, perform a check using a predicate on object
3461.             // The predicate: Is the current object owned by req.owner_ref?
3462.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3463.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3464.                 // Step 3: if the check passes, delete the object
3465.                 let delete_req = DeleteRequest {
3466.                     key: req.key,
3467.                     preconditions: None,
3468.                 };
3469.                 let (s_prime, delete_resp) = handle_delete_request(delete_req, s);
3470.                 (s_prime, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: delete_resp.res}))
3471.             } else {
3472.                 (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(APIError::TransactionAbort)}))
3473.             }
3474.         }
3475.         Err(err) => (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(err)}))
3476.     }
3477. }
