3479. pub open spec fn handle_get_then_update_request_msg(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3480.     recommends
3481.         msg.content.is_get_then_update_request(),
3482. {
3483.     let req = msg.content.get_get_then_update_request();
3484.     // Step 1: get the object
3485.     let get_req = GetRequest {
3486.         key: req.key()
3487.     };
3488.     let get_resp = handle_get_request(get_req, s);
3489.     match get_resp.res {
3490.         Ok(_) => {
3491.             let current_obj = s.resources[req.key()];
3492.             // Step 2: if the object exists, perform a check using a predicate on object
3493.             // The predicate: Is the current object owned by req.owner_ref?
3494.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3495.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3496.                 // Step 3: if the check passes, overwrite the object with the new one
3497.                 // Note that resource_version and uid comes from the current object to avoid conflict error
3498.                 let new_obj = DynamicObjectView {
3499.                     metadata: ObjectMetaView {
3500.                         resource_version: current_obj.metadata.resource_version,
3501.                         uid: current_obj.metadata.uid,
3502.                         ..req.obj.metadata
3503.                     },
3504.                     ..req.obj
3505.                 };
3506.                 let update_req = UpdateRequest {
3507.                     name: req.name,
3508.                     namespace: req.namespace,
3509.                     obj: new_obj,
3510.                 };
3511.                 let (s_prime, update_resp) = handle_update_request(installed_types, update_req, s);
3512.                 (s_prime, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: update_resp.res}))
3513.             } else {
3514.                 (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(APIError::TransactionAbort)}))
3515.             }
3516.         }
3517.         Err(err) => (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(err)}))
3518.     }
3519. }
