3570. // File: kubernetes_cluster/spec/builtin_controllers/garbage_collector.rs
3571. pub open spec fn run_garbage_collector() -> BuiltinControllersAction {
3572.     Action {
3573.         precondition: |input: BuiltinControllersActionInput, s: ()| {
3574.             let resources = input.resources;
3575.             let key = input.key;
3576.             let owner_references = resources[key].metadata.owner_references->0;
3577.             // The garbage collector is chosen by the top level state machine
3578.             &&& input.choice.is_GarbageCollector()
3579.             // The object exists in the cluster state
3580.             &&& resources.contains_key(input.key)
3581.             // and it has at least one owner reference
3582.             &&& resources[key].metadata.owner_references is Some
3583.             &&& resources[key].metadata.owner_references->0.len() > 0
3584.             // The garbage collector decides whether to delete an object by checking its owner references,
3585.             // it deletes the object if for each owner reference...
3586.             &&& forall |i| #![trigger owner_references[i]] 0 <= i < owner_references.len() ==> {
3587.                 // the referred owner object does not exist in the cluster state
3588.                 ||| !resources.contains_key(owner_reference_to_object_reference(owner_references[i], key.namespace))
3589.                 // or it exists but has a different uid
3590.                 // (which means the actual owner was deleted and another object with the same name gets created again)
3591.                 ||| resources[owner_reference_to_object_reference(owner_references[i], key.namespace)].metadata.uid != Some(owner_references[i].uid)
3592.             }
3593.         },
3594.         transition: |input: BuiltinControllersActionInput, s: ()| {
3595.             // GC set the preconditions to the object's uid in its delete request
3596.             // See https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/controller/garbagecollector/operations.go#L52-L61
3597.             let preconditions = PreconditionsView {
3598.                 uid: input.resources[input.key].metadata.uid,
3599.                 resource_version: None,
3600.             };
3601.             let delete_req_msg = built_in_controller_req_msg(
3602.                 input.rpc_id_allocator.allocate().1, delete_req_msg_content(input.key, Some(preconditions))
3603.             );
3604.             let output = BuiltinControllersActionOutput {
3605.                 send: Multiset::singleton(delete_req_msg),
3606.                 rpc_id_allocator: input.rpc_id_allocator.allocate().0,
3607.             };
3608.             ((), output)
3609.         },
3610.     }
3611. }
