     pub open spec fn schedule_controller_reconcile(self) -> Action<ClusterState, (int, ObjectRef), ()> {
         Action {
             precondition: |input: (int, ObjectRef), s: ClusterState| {
                 let controller_id = input.0;
                 let object_key = input.1;
