                 &&& req_msg.dst.is_APIServer()
                 &&& req_msg.content.is_APIRequest()
                 &&& result(input, s).is_Enabled()
             },
             transition: |input: (Message, APIError), s: ClusterState| {
                 (ClusterState {
                     network: result(input, s).get_Enabled_0(),
                     ..s
