 pub proof fn lemma_always_there_is_no_request_msg_to_external_from_controller(
     spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
 )
 requires
     spec.entails(lift_state(cluster.init())),
     spec.entails(always(lift_action(cluster.next()))),
     cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
     cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
 ensures
     spec.entails(always(lift_state(Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)))),
 {
     // Strengthen the state predicate by unfolding `Cluster::there_is_no_request_msg_to_external_from_controller`.
     // The cluster's transition only changes `network.in_flight` by moving/adding messages,
     // and controller actions only generate Kubernetes requests to the API server
     // because `vrs_controller_model()` has `external_model: None`.
     //
     // As a result, the invariant holds for the initial network state and is preserved by
     // every step of `cluster.next()`. We can therefore lift it to the always form using
     // `init_invariant`.
     init_invariant(
         spec,
         cluster.init(),
         cluster.next(),
         Cluster::there_is_no_request_msg_to_external_from_controller(controller_id),
     );
 }
 }

