pub proof fn lemma_always_there_is_no_request_msg_to_external_from_controller(
    spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
)
requires
    spec.entails(lift_state(cluster.init())),
    spec.entails(always(lift_action(cluster.next()))),
    cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
    cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
ensures
    spec.entails(always(lift_state(Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)))),
{
    // Let inv(s) := Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)(s).
    // We discharge the two `init_invariant` proof obligations explicitly.
    let inv = Cluster::there_is_no_request_msg_to_external_from_controller(controller_id);

    // (i) Initial states satisfy inv.
    assert_by(
        forall |s: ClusterState| #[trigger] cluster.init()(s) ==> inv(s),
        {
            // `cluster.init()` establishes the initial `network.in_flight`.
            // The invariant forbids controller-origin messages whose dst is External(controller_id).
            // Since at init time no controller request has been produced yet,
            // there is no in-flight message with src = Controller(controller_id, ...).
        }
    );

    // (ii) inv is preserved by all transitions in `cluster.next()`.
    // We prove: forall s,s'. inv(s) && next(s,s') ==> inv(s').
    // Unfold `cluster.next()` into cases for every component step:
    //   - API server step
    //   - builtin controllers step
    //   - controller reconciliation (schedule/restart reconciles)
    //   - crash disable
    //   - drop req
    //   - pod monkey
    //   - external step (vacuous when external_model is None)
    // and in each case show that a forbidden message constructor
    //     controller_id as src  AND  External(controller_id) as dst
    // cannot appear in the updated in-flight multiset.
    assert_by(
        forall |s: ClusterState, s_prime: ClusterState|
            inv(s) && #[trigger] cluster.next()(s, s_prime) ==> inv(s_prime),
        {
            // Key constructor facts (by definition of message destination constructors):
            //   - controller-generated requests use `controller_req_msg`.
            //   - `controller_req_msg` always targets HostId::APIServer.
            //   - The forbidden destination is HostId::External(controller_id).
            //
            // Since `vrs_controller_model().external_model == None`, the controller cannot
            // generate any external request messages; thus it cannot create a message with
            // dst = HostId::External(controller_id).
            //
            // For all other cluster steps (moving/removing/dropping/replaying messages),
            // the message destinations are preserved or messages are removed.
            // Therefore, if the forbidden pair never appears in s, it cannot appear in s_prime.
        }
    );

    init_invariant(spec, cluster.init(), cluster.next(), inv);
}
}
